   rules 5/6    : 10 hub key(s) resolve on this view, so its hubs and its 27 link(s)
                  are derived FROM here and not from anywhere else.
   satellites   : SAT_POLICY_COINSURANCE, SAT_POLICY_REFUND_DETAIL, SAT_PRODUCT_EXCLUSION_CATALOGUE, SAT_PRODUCT_HEALTH_MEMBERSHIP_RULES, SAT_PRODUCT_RATING_FACTOR, SAT_RISK_MOTOR_VEHICLE
   links        : LNK_CHANNEL_ORG_UNIT, LNK_CLAIM_LOCATION, LNK_CLAIM_PARTY, LNK_CLAIM_POLICY, LNK_CLAIM_RISK_OBJECT, LNK_ORG_UNIT_HIERARCHY
