{{ config(materialized='view') }}

with t0 as (
    select
        md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|INSURED|' || coalesce(nullif(trim(first_name),''),'') || '|' || coalesce(nullif(trim(middle_name),''),'') || '|' || coalesce(nullif(trim(last_name),''),'') || '|' || coalesce(nullif(trim(to_char(date_of_birth)),''),''), '|INSURED||||')))) as HUB_PARTY_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME,
        md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|NOMINEE|' || coalesce(nullif(trim(nominee_name),''),''), '|NOMINEE|')))) as HUB_PARTY_BK__CONTRACT_ID_NOMINEE_NOMINEE_NAME,
        nullif(trim(contract_id),'') as HUB_POLICY_BK__CONTRACT_ID,
        md5(normalise(upper(nullif(coalesce(nullif(trim(contract_id),''),'') || '|INSURED|' || coalesce(nullif(trim(first_name),''),'') || '|' || coalesce(nullif(trim(middle_name),''),'') || '|' || coalesce(nullif(trim(last_name),''),'') || '|' || coalesce(nullif(trim(to_char(date_of_birth)),''),''), '|INSURED||||')))) as HUB_RISK_OBJECT_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME,
        borrower_type
    from {{ ref('stg_ba_ccp_insured_details') }}
    qualify row_number() over (partition by HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME, borrower_type order by HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME, borrower_type) = 1
),

t1 as (
    select
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('LOANACC:' || nullif(trim(LOAN_ACC_NUMBER),''), 'LOANACC:') as HUB_RISK_OBJECT_BK__LOANACC_LOAN_ACC_NUMBER,
        bank_name,
        co_ins_type,
        loan_period,
        other_loan_type,
        refund_reason,
        sanctioned_loan,
        type_loan
    from {{ ref('stg_ba_ccp_sub_mater_dtls') }}
    qualify row_number() over (partition by HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__LOANACC_LOAN_ACC_NUMBER order by HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__LOANACC_LOAN_ACC_NUMBER) = 1
),

t2 as (
    select
        policy_ref as HUB_POLICY_BK__POLICY_REF,
        quote_ref as HUB_QUOTE_BK__QUOTE_REF,
        alwnat_dtls,
        natadd_brnchld_day,
        natadd_spouse_day,
        prem_cal_1,
        prem_cal_2,
        prem_cal_3
    from {{ ref('stg_ecard_pol_dtls_config') }}
    qualify row_number() over (partition by HUB_POLICY_BK__POLICY_REF, HUB_QUOTE_BK__QUOTE_REF order by HUB_POLICY_BK__POLICY_REF, HUB_QUOTE_BK__QUOTE_REF) = 1
),

t3 as (
    select
        claim_id as HUB_CLAIM_BK__CLAIM_ID,
        ldr_pid as HUB_PARTY_BK__LDR_PID,
        policy_ref as HUB_POLICY_BK__POLICY_REF,
        prod_cd as HUB_PRODUCT_BK__PROD_CD,
        insurco_policy_no
    from {{ ref('stg_hm_coinsu_clm_dtls') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID, HUB_PARTY_BK__LDR_PID, HUB_POLICY_BK__POLICY_REF, HUB_PRODUCT_BK__PROD_CD order by HUB_CLAIM_BK__CLAIM_ID, HUB_PARTY_BK__LDR_PID, HUB_POLICY_BK__POLICY_REF, HUB_PRODUCT_BK__PROD_CD) = 1
),

t4 as (
    select
        partner_id as HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID,
        bank_ac_no as HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO,
        member_id as HUB_PARTY_BK__MEMBER_ID,
        contract_id as HUB_POLICY_BK__CONTRACT_ID,
        product_code as HUB_PRODUCT_BK__PRODUCT_CODE,
        refund_premium
    from {{ ref('stg_hm_member_dtls') }}
    qualify row_number() over (partition by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_PARTY_BK__MEMBER_ID, HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_CODE order by HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID, HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO, HUB_PARTY_BK__MEMBER_ID, HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_CODE) = 1
),

t5 as (
    select
        md5(normalise(upper(nullif(coalesce(nullif(trim(HAT_ID_CITY),''),'') || '|' || coalesce(nullif(trim(HAT_ID_STATE),''),''), '|')))) as HUB_LOCATION_BK__HAT_ID_CITY_HAT_ID_STATE,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('MEMBER:' || coalesce(nullif(trim(CONTRACT_ID),''),'') || '#' || coalesce(nullif(trim(MEMBER_ID),''),''), 'MEMBER:#') as HUB_RISK_OBJECT_BK__MEMBER_CONTRACT_ID_MEMBER_ID
    from {{ ref('stg_hm_member_hlth_dtls') }}
    qualify row_number() over (partition by HUB_LOCATION_BK__HAT_ID_CITY_HAT_ID_STATE, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_CONTRACT_ID_MEMBER_ID order by HUB_LOCATION_BK__HAT_ID_CITY_HAT_ID_STATE, HUB_POLICY_BK__CONTRACT_ID, HUB_RISK_OBJECT_BK__MEMBER_CONTRACT_ID_MEMBER_ID) = 1
),

t6 as (
    select
        md5(normalise(upper(nullif(coalesce(nullif(trim(ADDRESS),''),'') || '|' || coalesce(nullif(trim(CITY),''),'') || '|' || coalesce(nullif(trim(REGION),''),''), '||')))) as HUB_LOCATION_BK__ADDRESS_CITY_REGION,
        md5(normalise(upper(nullif(coalesce(nullif(trim(INSURED_ADDRESS),''),'') || '|' || coalesce(nullif(trim(PINCODE),''),''), '|')))) as HUB_LOCATION_BK__INSURED_ADDRESS_PINCODE,
        md5(normalise(upper(nullif(trim(MAILING_PINCODE),'')))) as HUB_LOCATION_BK__MAILING_PINCODE,
        nullif(trim(BRANCH_CODE),'') as HUB_ORG_UNIT_BK__BRANCH_CODE,
        nullif(trim(DEPARTMENT_CODE),'') as HUB_ORG_UNIT_BK__DEPARTMENT_CODE,
        md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|')))) as HUB_PARTY_BK__CONTRACT_ID_INSURED_INSURED_NAME,
        nullif('PARTID:' || nullif(trim(PART_ID),''), 'PARTID:') as HUB_PARTY_BK__PARTID_PART_ID,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('PRODUCT:' || nullif(trim(PRODUCT_CODE),''), 'PRODUCT:') as HUB_PRODUCT_BK__PRODUCT_PRODUCT_CODE,
        coins_dtls,
        coins_our_share,
        vehicle_make,
        vehicle_model,
        vehicle_subtype,
        vehicle_type
    from {{ ref('stg_policy_summary') }}
    qualify row_number() over (partition by HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_PRODUCT_CODE order by HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__PRODUCT_PRODUCT_CODE) = 1
),

t7 as (
    select
        nullif('PARTNER:' || nullif(trim(PARTNER_ID),''), 'PARTNER:') as HUB_PARTY_BK__PARTNER_PARTNER_ID,
        nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|') as HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID,
        member_dob_yn,
        mem_backdate_limit,
        mem_data_bulk_upload,
        pin_code_val_yn,
        self_exclude
    from {{ ref('stg_ctngy_scheme_plans') }}
    qualify row_number() over (partition by HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID order by HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID) = 1
)

select
    t3.HUB_CLAIM_BK__CLAIM_ID as HUB_CLAIM_BK,
    t4.HUB_DISTRIBUTION_CHANNEL_BK__PARTNER_ID as HUB_DISTRIBUTION_CHANNEL_BK,
    t4.HUB_FINANCIAL_ACCOUNT_BK__BANK_AC_NO as HUB_FINANCIAL_ACCOUNT_BK,
