    coalesce(t3.HUB_PARTY_BK__LDR_PID, t4.HUB_PARTY_BK__MEMBER_ID, t7.HUB_PARTY_BK__PARTNER_PARTNER_ID) as HUB_PARTY_BK,
    coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID, t2.HUB_POLICY_BK__POLICY_REF, t3.HUB_POLICY_BK__POLICY_REF, t4.HUB_POLICY_BK__CONTRACT_ID, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__CONTRACT_ID) as HUB_POLICY_BK,
