    t0.HUB_PARTY_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME as T0__HUB_PARTY_BK__CONTRACT_ID_INSURED_FIRST_NAME_MIDDLE_NAME,
    t0.HUB_PARTY_BK__CONTRACT_ID_NOMINEE_NOMINEE_NAME as T0__HUB_PARTY_BK__CONTRACT_ID_NOMINEE_NOMINEE_NAME,
    t6.HUB_LOCATION_BK__ADDRESS_CITY_REGION as T6__HUB_LOCATION_BK__ADDRESS_CITY_REGION,
    t6.HUB_LOCATION_BK__INSURED_ADDRESS_PINCODE as T6__HUB_LOCATION_BK__INSURED_ADDRESS_PINCODE,
