    t3.insurco_policy_no as CO_INSURANCE_REFERENCE_NUMBER,
    t6.coins_our_share as CO_INSURANCE_SHARE_PERCENTAGE,
    t7.member_dob_yn as DOB_VALIDATION_RULE,
    t1.bank_name as FINANCIER_NAME,
    t0.borrower_type as INTEREST_TYPE,
    t1.sanctioned_loan as LOAN_AMOUNT,
    t1.loan_period as LOAN_TENOR,
    t1.type_loan as LOAN_TYPE,
    t6.vehicle_make as MAKE,
    t7.mem_backdate_limit as MEMBER_BACKDATING_LIMIT_DAYS,
    t7.mem_data_bulk_upload as MEMBER_BULK_UPLOAD_ALLOWED_INDICATOR,
    t7.pin_code_val_yn as MEMBER_PIN_CODE_VALIDATION_REQUIRED_INDICATOR,
    t6.vehicle_model as MODEL,
    t2.natadd_brnchld_day as NATURAL_ADDITION_NEWBORN_DAYS,
