    t2.natadd_spouse_day as NATURAL_ADDITION_SPOUSE_DAYS,
    t4.refund_premium as NET_REFUND_AMOUNT,
    t1.other_loan_type as OTHER_LOAN_TYPE_DESCRIPTION,
