from t0
full outer join t1 on t1.HUB_POLICY_BK__CONTRACT_ID = t0.HUB_POLICY_BK__CONTRACT_ID
full outer join t2 on t2.HUB_POLICY_BK__POLICY_REF = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID)
full outer join t3 on t3.HUB_POLICY_BK__POLICY_REF = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID, t2.HUB_POLICY_BK__POLICY_REF)
full outer join t4 on t4.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID, t2.HUB_POLICY_BK__POLICY_REF, t3.HUB_POLICY_BK__POLICY_REF)
full outer join t5 on t5.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID, t2.HUB_POLICY_BK__POLICY_REF, t3.HUB_POLICY_BK__POLICY_REF, t4.HUB_POLICY_BK__CONTRACT_ID)
full outer join t6 on t6.HUB_POLICY_BK__CONTRACT_ID = coalesce(t0.HUB_POLICY_BK__CONTRACT_ID, t1.HUB_POLICY_BK__CONTRACT_ID, t2.HUB_POLICY_BK__POLICY_REF, t3.HUB_POLICY_BK__POLICY_REF, t4.HUB_POLICY_BK__CONTRACT_ID, t5.HUB_POLICY_BK__CONTRACT_ID)
full outer join t7 on t7.HUB_PARTY_BK__PARTNER_PARTNER_ID = coalesce(t3.HUB_PARTY_BK__LDR_PID, t4.HUB_PARTY_BK__MEMBER_ID)
